package com.kuaixietech.payments;
import com.fasterxml.jackson.databind.*;
import com.kuaixietech.refunds.RefundModels.*;
import java.math.*;
import java.net.*;
import java.net.http.*;
import java.nio.charset.StandardCharsets;
import java.time.*;
import java.time.format.DateTimeFormatter;
import java.util.*;
import java.util.stream.Collectors;
import org.springframework.beans.factory.annotation.Qualifier;
import org.springframework.stereotype.Component;
import static com.kuaixietech.payments.PaymentModels.*;
/** Official original-transaction refund protocols. Does not handle order escrow or fabricate a bank bridge refund. */
@Component
public class OriginalPaymentRefundGateway {
 private final WechatNativeAdapter wechat;private final AlipayPageAdapter alipay;private final PaymentSecrets secrets;private final PaymentHttp http;private final ObjectMapper json=new ObjectMapper();
 public OriginalPaymentRefundGateway(@Qualifier("wechatNativeAdapter") WechatNativeAdapter wechat,AlipayPageAdapter alipay,PaymentSecrets secrets,PaymentHttp http){this.wechat=wechat;this.alipay=alipay;this.secrets=secrets;this.http=http;}
 public boolean configured(Merchant m){try{if(!(m.adapter().startsWith("wechat_")?wechat.configured(m):m.adapter().equals("alipay_rsa2")&&alipay.configured(m)))return false;secrets.value(m,"APP_ID");if(m.adapter().startsWith("wechat_"))secrets.value(m,"MERCHANT_ID");PaymentSecrets.sign(secrets.privateKey(m),"local-refund-key-check");secrets.publicKey(m,"PLATFORM_PUBLIC_KEY_FILE");return true;}catch(RuntimeException e){return false;}}
 public void prepare(Merchant merchant,Command command){validate(command);if(!configured(merchant))throw new IllegalStateException("REFUND_CHANNEL_NOT_CONFIGURED");if(merchant.adapter().startsWith("wechat_")){try{command.totalMinor().longValueExact();command.refundMinor().longValueExact();}catch(ArithmeticException e){throw new IllegalArgumentException("REFUND_AMOUNT_OUTSIDE_PROVIDER_RANGE");}wechatReason(command.reason());}}
 static String wechatReason(String reason){if(reason==null||reason.isBlank())throw new IllegalArgumentException("REFUND_REASON_REQUIRED");var result=new StringBuilder();int length=0;for(int point:reason.codePoints().toArray()){String value=new String(Character.toChars(point));int bytes=value.getBytes(StandardCharsets.UTF_8).length;if(length+bytes>80)break;result.append(value);length+=bytes;}return result.toString();}
 public Receipt submit(Merchant merchant,Command command){validate(command);if(!configured(merchant))throw new IllegalStateException("REFUND_CHANNEL_NOT_CONFIGURED");if(merchant.adapter().startsWith("wechat_")){try{var result=wechat.call(merchant,"POST","/v3/refund/domestic/refunds",json.writeValueAsString(Map.of("transaction_id",command.transactionId(),"out_refund_no",command.refundId(),"reason",wechatReason(command.reason()),"amount",Map.of("refund",command.refundMinor().longValueExact(),"total",command.totalMinor().longValueExact(),"currency","CNY"))));return wechatReceipt(command,result);}catch(IllegalStateException e){throw e;}catch(Exception e){throw new IllegalStateException("REFUND_PROVIDER_UNCONFIRMED");}}
  // Alipay mutation acknowledgement is never treated as a terminal receipt. Query the original out_request_no.
  var acknowledgement=alipayCall(merchant,"alipay.trade.refund","alipay_trade_refund_response",Map.of("trade_no",command.transactionId(),"out_request_no",command.refundId(),"refund_amount",CurrencyAmounts.major(command.refundMinor(),"CNY"),"refund_reason",command.reason()));
  if(!command.transactionId().equals(acknowledgement.path("trade_no").asText())||!command.paymentId().equals(acknowledgement.path("out_trade_no").asText()))throw new IllegalStateException("REFUND_PROVIDER_UNCONFIRMED");return query(merchant,command);
 }
 public Receipt query(Merchant merchant,Command command){validate(command);if(!configured(merchant))throw new IllegalStateException("REFUND_CHANNEL_NOT_CONFIGURED");if(merchant.adapter().startsWith("wechat_"))return wechatReceipt(command,wechat.call(merchant,"GET","/v3/refund/domestic/refunds/"+command.refundId(),""));var result=alipayCall(merchant,"alipay.trade.fastpay.refund.query","alipay_trade_fastpay_refund_query_response",Map.of("trade_no",command.transactionId(),"out_request_no",command.refundId()));return alipayReceipt(command,result);}
 private void validate(Command command){if(!command.refundId().matches("[a-f0-9]{32}")||!command.paymentId().matches("[a-f0-9]{32}")||command.transactionId()==null||command.transactionId().isBlank()||command.transactionId().length()>128||!"CNY".equals(command.currency())||command.totalMinor().signum()<=0||!command.totalMinor().equals(command.refundMinor()))throw new IllegalArgumentException("REFUND_COMMAND_REJECTED");}
 Receipt wechatReceipt(Command command,JsonNode response){String status=switch(response.path("status").asText()){case "SUCCESS"->"succeeded";case "CLOSED"->"closed";case "PROCESSING","ABNORMAL"->"processing";default->throw new IllegalStateException("REFUND_PROVIDER_UNCONFIRMED");};String currency=response.path("amount").path("currency").asText();BigInteger total=exactInteger(response.path("amount").get("total")),amount=exactInteger(response.path("amount").get("refund"));var receipt=new Receipt(response.path("out_refund_no").asText(),response.path("out_trade_no").asText(),response.path("transaction_id").asText(),response.path("refund_id").asText(),currency,total,amount,status);match(command,receipt);return receipt;}
 Receipt alipayReceipt(Command command,JsonNode response){String status=response.path("refund_status").asText();if(!"REFUND_SUCCESS".equals(status))throw new IllegalStateException("REFUND_PROVIDER_UNCONFIRMED");if(response.hasNonNull("total_amount"))try{if(!CurrencyAmounts.minor(response.path("total_amount").asText(),"CNY").equals(command.totalMinor()))throw new IllegalStateException("REFUND_RECEIPT_MISMATCH");}catch(IllegalArgumentException e){throw new IllegalStateException("REFUND_RECEIPT_MISMATCH");}String outRequest=response.path("out_request_no").asText();String currency=response.path("refund_currency").asText("CNY");BigInteger amount;try{amount=CurrencyAmounts.minor(response.path("refund_amount").asText(),"CNY");}catch(Exception e){throw new IllegalStateException("REFUND_PROVIDER_UNCONFIRMED");}var receipt=new Receipt(outRequest,response.path("out_trade_no").asText(),response.path("trade_no").asText(),outRequest,currency,command.totalMinor(),amount,"succeeded");match(command,receipt);return receipt;}
 private BigInteger exactInteger(JsonNode n){if(n==null||!n.isIntegralNumber())throw new IllegalStateException("REFUND_PROVIDER_UNCONFIRMED");return n.bigIntegerValue();}
 private void match(Command c,Receipt r){if(!c.refundId().equals(r.refundId())||!c.paymentId().equals(r.paymentId())||!c.transactionId().equals(r.transactionId())||!"CNY".equals(r.currency())||!c.totalMinor().equals(r.totalMinor())||!c.refundMinor().equals(r.refundMinor())||r.providerRefundId()==null||r.providerRefundId().isBlank()||r.providerRefundId().length()>128)throw new IllegalStateException("REFUND_RECEIPT_MISMATCH");}
 private JsonNode alipayCall(Merchant m,String method,String key,Map<String,Object> content){try{var params=new TreeMap<String,String>();params.put("app_id",secrets.value(m,"APP_ID"));params.put("method",method);params.put("format","JSON");params.put("charset","utf-8");params.put("sign_type","RSA2");params.put("timestamp",LocalDateTime.now(ZoneId.of("Asia/Shanghai")).format(DateTimeFormatter.ofPattern("yyyy-MM-dd HH:mm:ss")));params.put("version","1.0");params.put("biz_content",json.writeValueAsString(content));params.put("sign",PaymentSecrets.sign(secrets.privateKey(m),params.entrySet().stream().map(e->e.getKey()+"="+e.getValue()).collect(Collectors.joining("&"))));String body=params.entrySet().stream().map(e->URLEncoder.encode(e.getKey(),StandardCharsets.UTF_8)+"="+URLEncoder.encode(e.getValue(),StandardCharsets.UTF_8)).collect(Collectors.joining("&"));String raw=http.send(HttpRequest.newBuilder(URI.create("https://openapi.alipay.com/gateway.do")).timeout(Duration.ofSeconds(15)).header("Content-Type","application/x-www-form-urlencoded;charset=UTF-8").POST(HttpRequest.BodyPublishers.ofString(body)).build());JsonNode envelope=json.readTree(raw);if(!PaymentSecrets.verify(secrets.publicKey(m,"PLATFORM_PUBLIC_KEY_FILE"),AlipayPageAdapter.responseObject(raw,key),envelope.path("sign").asText()))throw new IllegalStateException("INVALID_PROVIDER_SIGNATURE");JsonNode result=envelope.path(key);if(!"10000".equals(result.path("code").asText()))throw new IllegalStateException("REFUND_PROVIDER_UNCONFIRMED");return result;}catch(IllegalStateException e){throw e;}catch(Exception e){throw new IllegalStateException("REFUND_PROVIDER_UNCONFIRMED");}}
}
